// Decide the verdict for ONE slogan from its USPTO trademark search results.
// This node runs once for all items: its input items are the dataset records
// the Apify actor returned for the slogan the Loop Over Items node is
// currently processing. It always returns exactly one verdict item, even
// when the actor returned no records at all.
const POD_CLASSES = ['IC 016', 'IC 021', 'IC 024', 'IC 025'];

function normalize(text) {
  return String(text ?? '')
    .toLowerCase()
    .trim()
    .replace(/[.!?]+$/, '')
    .trim();
}

// The slogan being checked, recovered from the loop item via item pairing.
// The fallback covers the empty-result case, where there is no input item
// to pair from.
let slogan = '';
try { slogan = $('Loop Over Items').item.json.Slogan ?? ''; } catch (e) { /* no paired item */ }
if (!slogan) {
  try { slogan = $('Loop Over Items').first().json.Slogan ?? ''; } catch (e) { /* ignore */ }
}
const target = normalize(slogan);

function inPodClass(item) {
  const classes = item.json.internationalClasses;
  return Array.isArray(classes) && classes.some((c) => POD_CLASSES.includes(c));
}

let risk = null;
let check = null;
for (const item of $input.all()) {
  const status = item.json.status;
  if (status && status !== 'LIVE') continue;
  if (!inPodClass(item)) continue;
  const mark = normalize(item.json.wordmark);
  if (!mark || !target) continue;
  // Last match wins, on purpose: this mirrors the Make version of this
  // template, whose write-order (default -> CHECK pass -> RISK pass) leaves
  // the LAST matching record in the sheet. Keeping the same rule here means
  // both templates report the same owner/serial for the same slogan
  // (verified on "Mama Bear": several exact matches exist in POD classes;
  // the last one is Amazon's, which is what the Make template writes back).
  if (mark === target) { risk = item; continue; }
  if (mark.includes(target) || target.includes(mark)) check = item;
}

if (risk) {
  return [{ json: { slogan, verdict: 'RISK — live trademark match', owner: risk.json.owner ?? '', serial: String(risk.json.serialNumber ?? '') } }];
}
if (check) {
  return [{ json: { slogan, verdict: 'CHECK — similar live mark', owner: check.json.owner ?? '', serial: String(check.json.serialNumber ?? '') } }];
}
return [{ json: { slogan, verdict: 'No live match found', owner: '', serial: '' } }];
